  getAppGitInfo(appKey: string): IGitAppVersion | undefined {
    if (!appKey) return undefined;
    const cleanKey = appKey.replace(/^\//, '').trim();
    return this.applications[cleanKey] || this.applications[cleanKey.toLowerCase()] || undefined;
  }
